#!/usr/bin/env python3
"""REA batch 05 Sound worlds: oracle/synthetic-rea-b05/<name>.wrl, scripts/<name>.json, media/*.wav.

  python3 -I oracle/tools/gen_rea_b05.py

Each world renders 40 frames (dt 0.016) of offline audio at 48 kHz, 2 channels, in step with the
frames (script key "audio", see oracle/x_ite-anim.mjs). The TimeSensor T and the Script S start the
source DEF O at the 12th time event. Worlds are synthetic; the WAV files are generated here.
Compared by oracle/tools/rea_b05.py.
"""
import json, math, os, struct

