def tick(actions, fields):
    body = '\n'.join(f'   if (n === {k}) {{ {a} }}' for k, a in actions)
    return f'''DEF K Script {{ directOutput TRUE {fields} inputOnly SFTime set_time initializeOnly SFInt32 n 0 url "ecmascript:
function set_time (value) {{ ++ n;
{body}
}}
" }}
ROUTE T.time TO K.set_time
'''

