def wav(name, rate, channels, frames):
    data = bytearray()
    for i in range(frames):
        for c in range(channels):
            v = 0.6 * math.sin(2 * math.pi * (300 + 200 * c) * i / rate) * (1 - i / frames) + 0.2 * (((i * 37 + c * 11) % 97) / 48.5 - 1)
            data += struct.pack("<h", int(round(v * 32767)))
    header = b"RIFF" + struct.pack("<I", 36 + len(data)) + b"WAVEfmt " + struct.pack("<IHHIIHH", 16, 1, channels, rate, rate * channels * 2, channels * 2, 16) + b"data" + struct.pack("<I", len(data))
    open(os.path.join(d, "media", name), "wb").write(header + data)


if __name__ == "__main__":
    os.makedirs(os.path.join(d, "scripts"), exist_ok=True)
    os.makedirs(os.path.join(d, "media"), exist_ok=True)
