    wav("tone22k-mono.wav", 22050, 1, 6000)

    for name, body in sorted(probes.items()):
        open(os.path.join(d, name + ".wrl"), "w").write(HEAD + body + "\n" + START + AFTER.get(name, ""))
        json.dump(SCRIPT, open(os.path.join(d, "scripts", name + ".json"), "w"))

    os.makedirs(os.path.join(d, "reload"), exist_ok=True)
    open(os.path.join(d, "reload", "reload-inline.wrl"), "w").write(RELOAD)
    open(os.path.join(d, "reload", "reload-inline-content.wrl"), "w").write(RELOAD_CONTENT)

    print(f"{len(probes)} worlds in {d}")
